from typing import Dict
from .facade import Analyzer


class ttitrace_analyzer(object):
    """
    Use example:
    >>> from taf.ul.ttitrace_analyzer import ttitrace_analyzer
    >>> ttitrace_analyzer.get_average_uplink_throughput('/path/to/trace/file.txt')
    >>> 4621.32
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @staticmethod
    def get_average_uplink_throughput(file_path):
        # type: (str) -> float
        """
        Get average throughput in UL (WCDMA)

        :param str file_path: path to file with traces (TXT or ZIP)
        return: average throughput in kbps
        """

        return Analyzer().get_average_uplink_throughput(file_path)

    @staticmethod
    def get_average_numOfPrbsAlloc(file_path, direction):
        """
        Get average throughput for given transfer direction, by analysing collected LTE TTI traces.

        :param str file_path: path to file with traces (TXT)
        :param str direction: transfer direction: 'uplink' or 'downlink' ('UL', 'ul', 'DL', 'dl' are also valid)
        return: average value
        """
        return Analyzer().get_average_numOfPrbsAlloc(file_path, direction)

    @staticmethod
    def get_average_totalPrbAvail(file_path, direction, filter_out_broken=True):
        """
        Get rounded average value of totalPrbAvail parameter form collected LTE TTI traces. Works for traces with multiple Ues.

        :param str file_path: path to file with traces (TXT)
        :param str direction: transfer direction: 'uplink' or 'downlink' ('UL', 'ul', 'DL', 'dl' are also valid)
        :param bool filter_out_broken: should "broken" traces be filtered out
        return: average value
        """
        return Analyzer().get_average_totalPrbAvail(file_path, direction, filter_out_broken)

    @staticmethod
    def get_average_throughput_lte(file_path):
        # type: (str) -> Dict
        """
        Get average throughput for given transfer direction, by analysing collected LTE TTI traces.

        .. note::

            Currently only direction='downlink' is implemented.

        .. note::

            The KW returns the value of average throughput calculated in a specific manner.
            Please, read the description of https://jira3.int.net.nokia.com/browse/TAT-17002 to get the idea.

        :param str file_path: path to file with traces
        return: a dictionary with Ue numbers as keys, and average throughput (in bits/s) as values
        """
        return Analyzer().get_average_throughput_lte(file_path, 'downlink')
